package com.paytrace.api; import com.paytrace.payment.PaymentService; import com.paytrace.provider.MockPaymentProvider; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(PaymentService.IdempotencyConflictException.class) ResponseEntity<Map<String,Object>> conflict(RuntimeException e){return problem(HttpStatus.CONFLICT,"idempotency-conflict",e.getMessage());}@ExceptionHandler(PaymentService.MissingIdempotencyKeyException.class) ResponseEntity<Map<String,Object>> missing(RuntimeException e){return problem(HttpStatus.BAD_REQUEST,"missing-idempotency-key",e.getMessage());}@ExceptionHandler(MockPaymentProvider.ProviderTimeoutException.class) ResponseEntity<Map<String,Object>> timeout(RuntimeException e){return problem(HttpStatus.GATEWAY_TIMEOUT,"provider-timeout",e.getMessage());}@ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,Object>> absent(RuntimeException e){return problem(HttpStatus.NOT_FOUND,"not-found",e.getMessage());}private ResponseEntity<Map<String,Object>> problem(HttpStatus status,String type,String detail){return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(Map.of("type",type,"title",status.getReasonPhrase(),"status",status.value(),"detail",detail,"timestamp",Instant.now().toString()));} }
